public static int calculateTimeNeeded(int N) {
    // handle edge case: N is odd
    if (N % 2 == 1) {
        throw new IllegalArgumentException("N must be even");
    }

    int timeNeeded = 0;
    while (N > 1) {
        int currentPair = N - 1; // the pair that is currently on the floor
        int oppositePair = N - currentPair; // the pair that is on the opposite side of the floor
        timeNeeded += oppositePair - currentPair; // the time needed to swap the current pair with the opposite pair
        N -= 2; // decrement N by 2 since we have processed two people
    }
    return timeNeeded;
}

