public List<List<Integer>> permute(int[] nums) {
    List<List<Integer>> permutations = new ArrayList<>();
    if (nums.length == 0) {
        return permutations;
    }
    permute(nums, 0, permutations);
    return permutations;
}

private void permute(int[] nums, int index, List<List<Integer>> permutations) {
    if (index == nums.length) {
        permutations.add(Arrays.asList(nums));
        return;
    }
    for (int i = 0; i < nums.length; i++) {
        int savedNum = nums[i];
        nums[i] = nums[index];
        nums[index] = savedNum;
        permute(nums, index + 1, permutations);
        nums[i] = savedNum;
        nums[index] = nums[index];
    }
}

