public void dfs(int[] nums, int n, int depth, boolean[] used, List<Integer> curList, List<List<Integer>> result) {   
   if (depth == n) {  
      result.add(new ArrayList<>(curList));  
      return;  
   }   

   for (int i = 0; i < n; i++) {  
      if (!used[i]) {  
         curList.add(nums[i]);   
         used[i] = true;   
         dfs(nums, n, depth + 1, used, curList, result);  
         curList.remove(curList.size() - 1);   
         used[i] = false;   
      }  
   }   
}

