    for (int i = 0; i < nums.length; i++) {
        int n = nums[i];
        // Swap n with the first element of the array
        nums[i] = nums[0];
        nums[0] = n;
        // Generate the permutations for the rest of the array
        List<List<Integer>> permutations = permute(Arrays.copyOfRange(nums, 1, nums.length));
        for (List<Integer> permutation : permutations) {
            // Add n to the beginning of each permutation
            permutation.add(0, n);
        }
        result.addAll(permutations);
        // Restore the original array
        nums[i] = n;
    }
    return result;
}

