    // Step 1: Sort the strings in descending order based on their length
    strings.sort((a, b) -> Integer.compare(b.length(), a.length()));

    // Step 2: For each string, check if it or its inverse is a substring of any of the other strings
    for (String str : strings) {
        for (String otherStr : strings) {
            if (otherStr.contains(str) || otherStr.contains(new StringBuilder(str).reverse().toString())) {
                return Math.max(str.length(), otherStr.length());
            }
        }
    }

