public static int countOilDeposits(char[][] grid) {
    int numOilDeposits = 0;
    HashSet<Integer> seenDeposits = new HashSet<>();
    for (int i = 0; i < grid.length; i++) {
        for (int j = 0; j < grid[i].length; j++) {
            if (grid[i][j] == '@') {
                int depositValue = getDepositValue(grid, i, j);
                if (!seenDeposits.contains(depositValue)) {
                    numOilDeposits++;
                    seenDeposits.add(depositValue);
                }
            }
        }
    }
    return numOilDeposits;
}

private static int getDepositValue(char[][] grid, int row, int col) {
    int value = 0;
    if (row - 1 >= 0 && grid[row - 1][col] == '@') {
        value += getDepositValue(grid, row - 1, col);
    }
    if (row + 1 < grid.length && grid[row + 1][col] == '@') {
        value += getDepositValue(grid, row + 1, col);
    }
    if (col - 1 >= 0 && grid[row][col - 1] == '@') {
        value += getDepositValue(grid, row, col - 1);
    }
    if (col + 1 < grid[row].length && grid[row][col + 1] == '@') {
        value += getDepositValue(grid, row, col + 1);
    }
    return value;
}

