private static void dfs(char[][] grid, int i, int j, boolean[][] visited) {
  if (i < 0 || i >= grid.length || j < 0 || j >= grid[0].length || grid[i][j] != '@' || visited[i][j]) {
    return;
  }

  visited[i][j] = true;

  dfs(grid, i - 1, j, visited);
  dfs(grid, i + 1, j, visited);
  dfs(grid, i, j - 1, visited);
  dfs(grid, i, j + 1, visited);
}

public static int maxRegions(int N) {
    // our approach is to draw a triangle with N sides
    // and then recursively divide the remaining regions
    // based on the size of the triangles

    // base case: if N is 1, there is only 1 triangle and 2 regions
    if (N == 1) {
        return 2;
    }

    // recursive case: if N is greater than 1, we can draw a triangle
    // with N sides and divide it into 2 regions
    int regions = maxRegions(N - 1) + 2;

    // now, we need to divide the remaining regions into smaller regions
    for (int i = 0; i < N - 2; i++) {
        regions += maxRegions(i + 2);
    }

    return regions;
}

