public static int maxRegions(int N) {
    // Base case: If N is 1, the maximum number of regions is 2
    if (N == 1) {
        return 2;
    }

    // Recursive case: If N is greater than 1, the maximum number of regions is 8 times the result of the recursive call with N-1
    return 8 * maxRegions(N-1);
}

