public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
  // check if the starting and ending coordinates are within the n-teresting space
  if (start[0] < 0 || start[0] >= n || start[1] < 0 || start[1] >= n ||
      end[0] < 0 || end[0] >= n || end[1] < 0 || end[1] >= n) {
    return "cannot be travelled";
  }

  // create a 2D array to represent the n-teresting space
  boolean[][] visited = new boolean[n][n];

  // initialize the starting n-tersection as visited
  visited[start[0]][start[1]] = true;

  // perform a depth-first search to find the ending n-tersection
  if (dfs(visited, start, end, paths)) {
    return "can be travelled";
  } else {
    return "cannot be travelled";
  }
}

private static boolean dfs(boolean[][] visited, int[] current, int[] end, int[][] paths) {
  // if the current n-tersection is the ending n-tersection, return true
  if (current[0] == end[0] && current[1] == end[1]) {
    return true;
  }

  // for each neighbor of the current n-tersection
  for (int[] neighbor : paths[current[0]][current[1]]) {
    // if the neighbor has not been visited, mark it as visited and recursively search its neighbors
    if (!visited[neighbor[0]][neighbor[1]]) {
      visited[neighbor[0]][neighbor[1]] = true;
      if (dfs(visited, neighbor, end, paths)) {
        return true;
      }
    }
  }

  // if no path was found to the ending n-tersection, return false
  return false;
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    /*
    * This method checks if a given maze can be traveled by starting at the
    * given starting position and ending at the given ending position. It
    * does this by performing a Depth-First Search algorithm on the maze,
    * marking the positions it has visited and backtracking if it reaches a
    * dead end.
    */

    // Initialize the visited positions
    boolean[][] visited = new boolean[n][n];
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            visited[i][j] = false;
        }
    }

    // Perform the DFS algorithm
    Stack<int[]> stack = new Stack<>();
    stack.push(start);
    while (!stack.isEmpty()) {
        int[] currentPosition = stack.pop();
        if (currentPosition[0] == end[0] && currentPosition[1] == end[1]) {
            return "can be travelled";
        }
        for (int[] neighbour : getNeighbours(currentPosition, paths)) {
            if (!visited[neighbour[0]][neighbour[1]]) {
                visited[neighbour[0]][neighbour[1]] = true;
                stack.push(neighbour);
            }
        }
    }
    return "cannot be travelled";
}

private static int[][] getNeighbours(int[] position, int[][] paths) {
    List<int[]> neighbours = new ArrayList<>();
    for (int[] path : paths) {
        if (path[0] == position[0] && path[1] == position[1]) {
            neighbours.add(new int[] { path[1], path[2] });
        }
    }
    return neighbours.toArray(new int[neighbours.size()][]);
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Initialize the stack to store the n-tersections to be visited
    Stack<int[]> stack = new Stack<>();

    // Add the starting n-tersection to the stack
    stack.push(start);

    // Initialize a visited array to keep track of the n-tersections that have been visited
    boolean[] visited = new boolean[n];
    visited[start[0] * n + start[1]] = true;

    // Loop until the stack is empty
    while (!stack.isEmpty()) {
        // Get the current n-tersection coordinates
        int[] current = stack.pop();

        // If the current n-tersection is the ending n-tersection, return "can be travelled"
        if (current[0] == end[0] && current[1] == end[1]) {
            return "can be travelled";
        }

        // Loop through all the paths from the current n-tersection
        for (int i = 0; i < paths.length; i++) {
            // If the path is not visited, add the adjacent n-tersection to the stack
            if (!visited[paths[i][0] * n + paths[i][1]]) {
                stack.push(paths[i]);
            }
        }

        // Mark the current n-tersection as visited
        visited[current[0] * n + current[1]] = true;
    }

    // If the stack is empty and the ending n-tersection has not been reached, return "cannot be travelled"
    return "cannot be travelled";
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {

  // Check if the start and end points are valid
  if (!isValidPoint(start) || !isValidPoint(end)) {
    return "cannot be travelled";
  }

  // Initialize a set to keep track of visited n-tersections
  Set<int[]> visited = new HashSet<>();

  // Initialize a queue to perform BFS
  Queue<int[]> queue = new LinkedList<>();

  // Add the start point to the queue and visited set
  queue.add(start);
  visited.add(start);

  // Perform BFS
  while (!queue.isEmpty()) {
    int[] current = queue.poll();
    // If the current n-tersection is the end point, return "can be travelled"
    if (current[0] == end[0] && current[1] == end[1]) {
      return "can be travelled";
    }
    // For each adjacent n-tersection, check if it is valid and hasn't been visited before
    for (int i = 0; i < paths.length; i++) {
      int[] adjacent = getAdjacentPoint(current, i);
      if (adjacent != null && !visited.contains(adjacent)) {
        queue.add(adjacent);
        visited.add(adjacent);
      }
    }
  }

  // If we have visited all n-tersections and didn't find the end point, return "cannot be travelled"
  return "cannot be travelled";
}

private static boolean isValidPoint(int[] point) {
  return point[0] >= 0 && point[0] < n && point[1] >= 0 && point[1] < n;
}

private static int[] getAdjacentPoint(int[] point, int index) {
  int x = point[0] + paths[index][0];
  int y = point[1] + paths[index][1];
  if (x >= 0 && x < n && y >= 0 && y < n) {
    return new int[] { x, y };
  } else {
    return null;
  }
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // check if the starting and ending n-tersections are valid
    if (start[0] < 0 || start[0] >= n || start[1] < 0 || start[1] >= n || end[0] < 0 || end[0] >= n || end[1] < 0 || end[1] >= n) {
        return "cannot be travelled";
    }

    // initialize the visited array
    boolean[][] visited = new boolean[n][n];

    // perform DFS to find the path from start to end
    Stack<int[]> stack = new Stack<>();
    stack.push(start);
    visited[start[0]][start[1]] = true;

    while (stack.isEmpty() == false) {
        int[] current = stack.pop();
        if (current[0] == end[0] && current[1] == end[1]) {
            return "can be travelled";
        }
        for (int[] neighbor : getNeighbors(current, paths)) {
            if (visited[neighbor[0]][neighbor[1]] == false) {
                visited[neighbor[0]][neighbor[1]] = true;
                stack.push(neighbor);
            }
        }
    }

    return "cannot be travelled";
}

private static int[][] getNeighbors(int[] current, int[][] paths) {
    List<int[]> neighbors = new ArrayList<>();
    for (int[] path : paths) {
        if (path[0] == current[0] && path[1] == current[1]) {
            neighbors.add(path[2]);
        }
    }
    return neighbors.toArray(new int[neighbors.size()][2]);
}

