private int findPivot(int[] nums) {
    int low = 0, high = nums.length-1;
    while(low <= high) {
        int mid = (low + high) / 2;
        if (nums[mid] < nums[mid+1]) {
            return mid+1;
        }
        if (nums[mid] < nums[mid-1]) {
            return mid;
        }
        if (nums[mid] == nums[high]) {
            low = mid + 1;
        } else {
            high = mid - 1;
        }
    }
    return -1;
}

