public double trimMean(int[] arr) {
    if (arr == null || arr.length == 0) {
        throw new IllegalArgumentException("Invalid input: The input array is null or empty.");
    }

    // Calculate the number of elements to remove from the beginning and end
    int removeBeginning = (int) Math.round((arr.length / 100.0) * 5.0);
    int removeEnd = (int) Math.round((arr.length / 100.0) * 5.0);

    // Remove the smallest elements from the beginning and largest elements from the end
    int[] sortedArr = Arrays.copyOfRange(arr, removeBeginning, arr.length - removeEnd);

    // Calculate the mean of the remaining elements
    double sum = 0.0;
    for (int i = 0; i < sortedArr.length; i++) {
        sum += sortedArr[i];
    }
    double mean = sum / sortedArr.length;

    return mean;
}

public double trimMean(int[] arr) {
    if (arr.length == 0) {
        throw new IllegalArgumentException("Input array is empty");
    }
    int n = arr.length;
    int removeCount = (int) (n * 0.05);
    if (removeCount * 2 >= n) {
        throw new IllegalArgumentException("Input array is too short to remove 5% of elements");
    }
    Arrays.sort(arr);
    int startIdx = removeCount;
    int endIdx = n - removeCount - 1;
    double sum = 0;
    for (int i = startIdx; i <= endIdx; i++) {
        sum += arr[i];
    }
    return sum / (endIdx - startIdx + 1);
}

