    Arrays.sort(arr);

    // Step 2: Calculate the length of the trimmed array
    int trimmedLength = (int) Math.floor(arr.length * 0.9);

    // Step 3: Calculate the mean of the trimmed array
    double sum = 0;
    for (int i = 0; i < trimmedLength; i++) {
        sum += arr[i];
    }
    double mean = sum / trimmedLength;

    // Step 4: Return the mean with an error of 10^-5
    return Math.round(mean * 100000) / 100000;
}

