    int minTime = 0;

    // Initialize the visited array to keep track of the nodes that have been visited
    boolean[] visited = new boolean[n];
    visited[0] = true;

    // Initialize the queue to store the nodes to be visited
    Queue<Integer> queue = new LinkedList<>();
    queue.add(0);

    // Loop while the queue is not empty
    while (!queue.isEmpty()) {
        // Get the current node
        int currentNode = queue.poll();

        // Loop through the neighbors of the current node
        for (int neighbor : edges[currentNode]) {
            // If the neighbor has not been visited and has an apple
            if (!visited[neighbor] && hasApple[neighbor]) {
                // Update the minimum time required
                minTime += 2;

                // Mark the neighbor as visited
                visited[neighbor] = true;

                // Add the neighbor to the queue
                queue.add(neighbor);
            }
        }
    }

    return minTime;
}

