  Graph graph = new Graph(n, edges);

  // Initialize a variable to keep track of the minimum time
  int minTime = 0;

  // Traverse the graph from node 0
  for (int i = 0; i < n; i++) {
    int currentNode = 0;
    int currentDistance = 0;
    while (currentNode != i) {
      // If the current node has an apple, update the minimum time
      if (hasApple[currentNode]) {
        minTime += currentDistance;
      }

      // Get the next node in the graph
      currentNode = graph.getNextNode();
      if (currentNode == -1) {
        break;
      }

      // Update the distance to the next node
      currentDistance += graph.getDistance(currentNode);
    }
  }

