}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
  if (n <= 0 || edges == null || hasApple == null || edges.length != n || hasApple.length != n) {
    throw new IllegalArgumentException("Invalid input");
  }

  // Initialize the minimum time to 0
  int minTime = 0;

  // Create a visited array to keep track of the visited nodes
  boolean[] visited = new boolean[n];

  // DFS to traverse the tree
  dfs(edges, hasApple, visited, 0, minTime);

  return minTime;
}

private void dfs(int[][] edges, boolean[] hasApple, boolean[] visited, int node, int minTime) {
  if (visited[node]) {
    return;
  }

  // If the current node has an apple, update the minimum time
  if (hasApple[node]) {
    minTime = Math.max(minTime, 1);
  }

  // Mark the current node as visited
  visited[node] = true;

  // Recursively call DFS on the unvisited neighbors
  for (int neighbor : edges[node]) {
    if (!visited[neighbor]) {
      dfs(edges, hasApple, visited, neighbor, minTime);
    }
  }
}

public String sortString(String s) {
    if (s == null || s.length() <= 1) {
