        char smallest = s.charAt(0);
        int smallestIndex = 0;
        for (int i = 1; i < s.length(); i++) {
            char current = s.charAt(i);
            if (current < smallest) {
                smallest = current;
                smallestIndex = i;
            }
        }
        sorted += smallest;
        s = s.substring(0, smallestIndex) + s.substring(smallestIndex + 1);
    }
