public String sortString(String s) {
    if (s == null || s.length() <= 1) {
        return s;
    }

    // Initialize the result string
    StringBuilder result = new StringBuilder();

    // Sort the characters of s
    char[] sortedChars = s.toCharArray();
    Arrays.sort(sortedChars);

    // Repeat the steps from 1 to 6 until all characters are used
    while (result.length() < s.length()) {
        // If the smallest or the largest character appears more than once, choose any occurrence
        if (containsMultiple(sortedChars, sortedChars[0])) {
            result.append(sortedChars[0]);
            sortedChars = removeElement(sortedChars, sortedChars[0]);
        } else if (containsMultiple(sortedChars, sortedChars[sortedChars.length - 1])) {
            result.append(sortedChars[sortedChars.length - 1]);
            sortedChars = removeElement(sortedChars, sortedChars[sortedChars.length - 1]);
        }

        // If there are still unused characters, repeat steps 1-6
        if (sortedChars.length > 0) {
            result.append(sortedChars[0]);
            sortedChars = removeElement(sortedChars, sortedChars[0]);
        }
    }

    return result.toString();
}

private boolean containsMultiple(char[] sortedChars, char c) {
    int count = 0;
    for (char sortedChar : sortedChars) {
        if (sortedChar == c) {
            count++;
        }
    }
    return count > 1;
}

private char[] removeElement(char[] array, char c) {
    int index = 0;
    for (char element : array) {
        if (element == c) {
            break;
        }
        index++;
    }
    char[] newArray = new char[array.length - 1];
    System.arraycopy(array, 0, newArray, 0, index);
    System.arraycopy(array, index + 1, newArray, index, newArray.length - index);
    return newArray;
}

