public int minCostClimbingStairs(int[] cost) {
    int minCost = Integer.MAX_VALUE;
    for (int i = 0; i < cost.length; i++) {
        int currentCost = cost[i];
        if (i == 0) {
            minCost = Math.min(minCost, currentCost);
        } else {
            int previousCost = cost[i - 1];
            minCost = Math.min(minCost, currentCost + previousCost);
        }
    }
    return minCost;
}

public int minCostClimbingStairs(int[] cost) {
    // Base case: If the cost array is empty or has only one element, return 0
    if (cost.length == 0 || cost.length == 1) {
      return 0;
    }

    // Initialize the minimum cost to reach the top of the floor
    int minCost = Integer.MAX_VALUE;

    // Iterate through the cost array and calculate the minimum cost
    for (int i = 0; i < cost.length - 1; i++) {
      // Calculate the cost of the current step and the next step
      int currentCost = cost[i];
      int nextCost = cost[i + 1];

      // Calculate the minimum cost of reaching the top of the floor
      // by taking the minimum of the current cost and the next cost
      minCost = Math.min(minCost, currentCost + nextCost);
    }

    return minCost;
  }

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    int[] dp = new int[n + 1];

    dp[0] = 0;
    dp[1] = 0;

    for (int i = 2; i <= n; i++) {
        dp[i] = Math.min(dp[i - 1] + cost[i - 1], dp[i - 2] + cost[i - 2]);
    }

    return dp[n];
}

public int minCostClimbingStairs(int[] cost) {
  int minCost = Integer.MAX_VALUE;
  int currentCost = 0;

  for (int i = 0; i < cost.length; i++) {
    currentCost += cost[i];
    if (i == cost.length - 1) {
      minCost = Math.min(minCost, currentCost);
    }
  }

  return minCost;
}

public int minCostClimbingStairs(int[] cost) {
    int minCost = cost[0]; // Minimum cost from the starting point
    int currentCost = 0; // Current cost of the path
    int previousCost = 0; // Previous cost of the path

    // Iterate through the cost array
    for (int i = 1; i < cost.length; i++) {
        currentCost = cost[i];

        // Calculate the minimum cost
        if (i == 1) {
            minCost = Math.min(minCost, previousCost + currentCost);
        } else {
            minCost = Math.min(minCost, previousCost + currentCost);
            previousCost = currentCost;
        }
    }

    return minCost;
}

