public int minOperations(int n) {
    int[] arr = new int[n];
    for (int i = 0; i < n; i++) {
        arr[i] = 2 * i + 1;
    }
    int minOperations = 0;
    for (int i = 1; i < n; i++) {
        int diff = Math.abs(arr[i] - arr[i - 1]);
        if (diff > 0) {
            int x = i, y = i - 1;
            if (arr[x] > arr[y]) {
                x = i - 1;
                y = i;
            }
            arr[x] -= 1;
            arr[y] += 1;
            minOperations++;
        }
    }
    return minOperations;
}

public int minOperations(int n) {
