    // Initialize the array
    for (int i = 0; i < n; i++) {
        arr[i] = (2 * i) + 1;
    }

    // Find the minimum element in the array
    int minElement = arr[0];
    for (int i = 1; i < n; i++) {
        if (arr[i] < minElement) {
            minElement = arr[i];
        }
    }

    // Calculate the number of operations required to make all elements equal to the minimum element
    for (int i = 0; i < n; i++) {
        if (arr[i] != minElement) {
            minOperations++;
        }
    }

    return minOperations;
}

