}

public int minOperations(int n) {
  // Calculate the target sum of all elements in arr
  int targetSum = (n * (n + 1)) / 2;

  // Initialize variables to keep track of the minimum number of operations
  int minOperations = Integer.MAX_VALUE;
  int currentSum = 0;

  // Iterate over the elements in arr and calculate the sum
  for (int i = 0; i < n; i++) {
    currentSum += arr[i];
  }

  // Calculate the difference between the current sum and the target sum
  int difference = Math.abs(currentSum - targetSum);

  // Update the minimum number of operations if necessary
  if (difference < minOperations) {
    minOperations = difference;
  }

  // Return the minimum number of operations
  return minOperations;
}

public int minOperations(int n) {
    // initialize the array with the given condition
    int[] arr = new int[n];
    for (int i = 0; i < n; i++) {
        arr[i] = (2 * i) + 1;
    }

    // initialize the minimum number of operations to zero
    int minOperations = 0;

    // loop through the array and find the minimum number of operations required to make all elements equal
    for (int i = 0; i < n; i++) {
        int minValue = arr[0];
        for (int j = 1; j < n; j++) {
            if (arr[j] < minValue) {
                minValue = arr[j];
            }
        }
        minOperations += (minValue - arr[i]) / 2;
        arr[i] = minValue;
    }

    return minOperations;
}

