public int findMinFibonacciNumbers(int k) {
    // Initialize the Fibonacci sequence
    int[] fibonacci = new int[k + 1];
    fibonacci[0] = 1;
    fibonacci[1] = 1;

    // Calculate the Fibonacci numbers up to k
    for (int i = 2; i <= k; i++) {
        fibonacci[i] = fibonacci[i - 1] + fibonacci[i - 2];
    }

    // Find the minimum number of Fibonacci numbers whose sum is equal to k
    int minNumber = Integer.MAX_VALUE;
    for (int i = 0; i <= k; i++) {
        if (fibonacci[i] == k) {
            minNumber = 1;
            break;
        } else if (fibonacci[i] > k) {
            break;
        }
        for (int j = i + 1; j <= k; j++) {
            if (fibonacci[i] + fibonacci[j] == k) {
                minNumber = Math.min(minNumber, 2);
                break;
            }
        }
    }

    return minNumber;
}

public int findMinFibonacciNumbers(int k) {
    // Initialize a list to store the Fibonacci numbers
    List<Integer> fibList = new ArrayList<>();
    fibList.add(1);
    fibList.add(1);

    // Loop until we have found a Fibonacci number greater than k
    while (fibList.get(fibList.size() - 1) <= k) {
        // Get the last two Fibonacci numbers
        int fib1 = fibList.get(fibList.size() - 1);
        int fib2 = fibList.get(fibList.size() - 2);

        // Calculate the next Fibonacci number
        int fib3 = fib1 + fib2;

        // Add the next Fibonacci number to the list
        fibList.add(fib3);
    }

    // Initialize a variable to store the minimum number of Fibonacci numbers
    int minFibNumbers = 0;

    // Loop through the Fibonacci numbers in reverse order
    for (int i = fibList.size() - 1; i >= 0; i--) {
        // Check if the current Fibonacci number is less than or equal to k
        if (fibList.get(i) <= k) {
            // Increment the minimum number of Fibonacci numbers
            minFibNumbers++;

            // Subtract the current Fibonacci number from k
            k -= fibList.get(i);
        }
    }

    // Return the minimum number of Fibonacci numbers
    return minFibNumbers;
}

