        if (substring.equals(s)) {
            maxSubstrings++;
        }
    }

    return maxSubstrings;
}

public int maxUniqueSplit(String s) {
    if (s == null || s.length() == 0 || s.length() > 16) {
        return 0;
    }

    // The maximum number of unique substrings is equal to the length of the input string
    int max = s.length();

    // Initialize a set to store the unique substrings
    Set<String> unique = new HashSet<>();

    // Loop through the input string and split it on each character
    for (int i = 0; i < s.length(); i++) {
        String substring = s.substring(0, i + 1);
        if (unique.contains(substring)) {
            continue;
        }

        // Check if the substring can be reconstructed by concatenating the characters
        if (canReconstruct(substring, s)) {
            // The substring is unique, so add it to the set
            unique.add(substring);

            // Check if the substring is the longest so far
            if (substring.length() > max) {
                max = substring.length();
            }
        }
    }

    return max;
}

private boolean canReconstruct(String substring, String s) {
    // The substring cannot be reconstructed if it is empty
    if (substring.length() == 0) {
        return false;
    }

    // The substring can be reconstructed if it is a prefix of the input string
    for (int i = 0; i < s.length() - substring.length() + 1; i++) {
        if (s.substring(i, i + substring.length()).equals(substring)) {
            return true;
        }
    }

    // The substring cannot be reconstructed
    return false;
}

