public int minOperations(String[] logs) {
  // Initialize a stack to keep track of the current folder
  Stack<String> stack = new Stack<>();
  stack.push("main");

  // Iterate through the logs
  for (String log : logs) {
    // If the log is a ".." operation,
    // pop the current folder from the stack
    if (log.equals("..")) {
      stack.pop();
    } else {
      // If the log is a normal folder,
      // push it onto the stack
      stack.push(log);
    }
  }

  // The minimum number of steps is the size of the stack minus one
  // (since we started in the main folder)
  int minSteps = stack.size() - 1;

  // If the stack is empty, we are already in the main folder
  if (stack.isEmpty()) {
    minSteps = 0;
  }

  return minSteps;
}

