    }

    // Step 2: Calculate the maximum alphabet position for the given n and k
    int maxPosition = 0;
    for (int i = 1; i <= n; i++) {
        maxPosition += i;
        if (maxPosition >= k) {
            break;
        }
    }

    // Step 3: Generate the smallest string of length n and value k
    String smallestString = "";
    int value = 0;
    for (int i = n; i > 0; i--) {
        int alphabetPosition = maxPosition - value;
        if (alphabetPosition > 0) {
            smallestString = String.valueOf((char) (96 + alphabetPosition)) + smallestString;
            value += alphabetPosition;
        } else {
            smallestString = "a" + smallestString;
            value += 1;
        }
    }

    return smallestString;
}

