    if (low < 0 || high > 1000000000 || low > high) {
        throw new IllegalArgumentException("Invalid input range");
    }

    List<Integer> steppingNumbers = new ArrayList<>();

    // Iterate from low to high and check if each number is a stepping number
    for (int i = low; i <= high; i++) {
        if (isSteppingNumber(i)) {
