    Collections.sort(steppingNumbers);
    return steppingNumbers;
}

private static boolean isSteppingNumber(int n) {
    int prevDigit = n % 10;
    for (int i = 1; i < 10; i++) {
        int currentDigit = (n / (int) Math.pow(10, i)) % 10;
        if (currentDigit != prevDigit && Math.abs(currentDigit - prevDigit) != 1) {
            return false;
        }
        prevDigit = currentDigit;
    }
    return true;
}

public static List<Integer> findSteppingNumbers(int low, int high) {
