    if (low < 0 || high < 0 || low > high) {
        throw new IllegalArgumentException("Invalid input range");
    }

    // Initialize variables
    int current = low;
    int prev = low - 1;

    // Iterate through the range
    while (current <= high) {
        if (isSteppingNumber(current)) {
            steppingNumbers.add(current);
        }
        prev = current;
        current++;
    }

    // Sort and return the stepping numbers
    Collections.sort(steppingNumbers);
    return steppingNumbers;
}

