    int prev = n % 10;
    n = n / 10;
    while (n > 0) {
        int curr = n % 10;
        if (curr != prev + 1 && curr != prev - 1) {
            return false;
        }
        prev = curr;
        n = n / 10;
    }
    return true;
}

