    }

    int rows = mat.length;
    int cols = mat[0].length;
    int[] result = new int[rows * cols];
    int r = 0;
    int c = 0;
    int dir = 1;

    while (r < rows && c < cols) {
        result[r * cols + c] = mat[r][c];
        r += dir;
        c += dir;
        if (r >= rows && c >= cols) {
            dir = -dir;
            r -= dir;
            c -= dir;
        }
    }

    return result;
}

