            if (i + j >= rows - 1) {
                break;
            }
            result[i * cols + j] = mat[i][j];
        }
    }

    for (int i = cols - 1; i >= 0; i--) {
        for (int j = 0; j < rows; j++) {
            if (i + j >= rows - 1) {
