    int[] v3 = new int[] {points[2][0] - points[0][0], points[2][1] - points[0][1]};
    int crossProduct = v1[0] * v2[1] - v1[1] * v2[0];
    if (crossProduct == 0) {
        return false;
    }

    // step 3: check if the points form a boomerang
    double v1Length = Math.sqrt(v1[0] * v1[0] + v1[1] * v1[1]);
    double v2Length = Math.sqrt(v2[0] * v2[0] + v2[1] * v2[1]);
    double v3Length = Math.sqrt(v3[0] * v3[0] + v3[1] * v3[1]);
    if (v1Length * v2Length == v3Length) {
