public static int minPerfectSquareSum(int n) {
    int minCount = Integer.MAX_VALUE;
    for (int i = 1; i * i <= n; i++) {
        int count = 0;
        while (n > 0) {
            int sqrt = (int) Math.sqrt(n);
            count++;
            n -= sqrt * sqrt;
        }
        minCount = Math.min(minCount, count);
    }
    return minCount;
}

public static int minPerfectSquareSum(int n) {
    // Initialize a list to store the perfect square numbers
    List<Integer> perfectSquares = new ArrayList<>();

    // Iterate from 1 to sqrt(n)
    for (int i = 1; i * i <= n; i++) {
        // If i is a perfect square, add it to the list
        if (isPerfectSquare(i)) {
            perfectSquares.add(i);
        }
    }

    // Initialize the minimum number of perfect square numbers to n
    int minPerfectSquares = n;

    // Iterate through the list of perfect square numbers
    for (int i = 0; i < perfectSquares.size(); i++) {
        // If the current number is greater than the target, break the loop
        if (perfectSquares.get(i) > n) {
            break;
        }

        // If the current number is a perfect square, update the minimum number of perfect square numbers
        if (isPerfectSquare(perfectSquares.get(i))) {
            minPerfectSquares = Math.min(minPerfectSquares, 1 + minPerfectSquareSum(n - perfectSquares.get(i)));
        }
    }

    return minPerfectSquares;
}

private static boolean isPerfectSquare(int num) {
    int root = (int) Math.sqrt(num);
    return root * root == num;
}

public static int minPerfectSquareSum(int n) {
    int perfectSquares = 0;
    int currentSquare = 1;
    int currentSum = 0;

    while (currentSum < n) {
        currentSquare++;
        int currentSquareRoot = (int) Math.sqrt(currentSquare);
        if (currentSquareRoot * currentSquareRoot == currentSquare) {
            perfectSquares++;
            currentSum += currentSquare;
        }
    }

    return perfectSquares;
}

public static int minPerfectSquareSum(int n) {
    // Initialize a list to store the perfect square numbers
    List<Integer> perfectSquares = new ArrayList<>();

    // Iterate from 1 to sqrt(n)
    for (int i = 1; i * i <= n; i++) {
        // If i is a perfect square, add it to the list
        if (i * i == n) {
            perfectSquares.add(i);
        }
    }

    // Return the minimum number of perfect square numbers
    return perfectSquares.size();
}

public static int minPerfectSquareSum(int n) {
    if (n <= 0) {
        return 0;
    }
    int perfectSquares = 0;
    for (int i = 1; i <= Math.sqrt(n); i++) {
        perfectSquares += i * i;
    }
    return Math.min(perfectSquares, n);
}

public static String reverseWords(String s) {
    String[] words = s.split(" ");
    String reversed = "";
    for (String word : words) {
        StringBuilder sb = new StringBuilder(word);
        sb.reverse();
        reversed += sb.toString() + " ";
    }
    return reversed.trim();
}

